// ---------- drag the area diagram ----------
let dragMode=null;
const areaSvg=$('area');
function svgPt(e){
  const r=areaSvg.getBoundingClientRect(), vb=areaSvg.viewBox.baseVal;
  return {x:(e.clientX-r.left)*vb.width/r.width, y:(e.clientY-r.top)*vb.height/r.height};
}
function setSlider(id,v,min,max){ $(id).value=Math.min(max,Math.max(min,v)); }
function dragTo(e){
  const {x,y}=svgPt(e), X0=10,Y0=10,S=240;
  const frac=v=>Math.min(1,Math.max(0,v));
  exactPrior=null; hist=[];
  if(dragMode==='prior') setSlider('prior',frac((x-X0)/S)*100,0.1,99);
  else if(dragMode==='sens') setSlider('sens',Math.round(frac((y-Y0)/S)*200)/2,0,100);
  else setSlider('fpr',Math.round(frac((y-Y0)/S)*200)/2,0,100);
  PRESETS.forEach((_,j)=>$('pb'+j).classList.remove('on'));
  update();
}
areaSvg.addEventListener('pointerdown',e=>{
  const {x}=svgPt(e), div=10+240*(($('prior').value)/100);
  dragMode = Math.abs(x-div)<10 ? 'prior' : (x<div ? 'sens':'fpr');
  areaSvg.setPointerCapture(e.pointerId); dragTo(e);
});
areaSvg.addEventListener('pointermove',e=>{
  if(dragMode){dragTo(e);return;}
  const {x}=svgPt(e), div=10+240*(($('prior').value)/100);
  areaSvg.style.cursor = Math.abs(x-div)<10 ? 'ew-resize' : 'ns-resize';
});
areaSvg.addEventListener('pointerup',()=>dragMode=null);

// ---------- sequential updating ----------
function curParams(){ return {pH:exactPrior ?? $('prior').value/100, s:$('sens').value/100, f:$('fpr').value/100}; }
function observe(positive){
  const {pH,s,f}=curParams();
  const a = positive ? s : 1-s, b = positive ? f : 1-f;
  const d = a*pH + b*(1-pH); if(d===0) return;
  if(!hist.length) hist.push({v:pH});
  const np = a*pH/d;
  hist.push({v:np, pos:positive});
  exactPrior=np; update();
}
$('obsPos').onclick=()=>observe(true);
$('obsNeg').onclick=()=>observe(false);
$('obsReset').onclick=()=>{ exactPrior=null; hist=[]; update(); };

// ---------- simulation ----------
function runSim(n){
  const {pH,s,f}=curParams();
  for(let i=0;i<n;i++){
    const isH=Math.random()<pH, ev=Math.random()<(isH?s:f);
    sim.n++; if(ev){ sim.pos++; if(isH) sim.posH++; }
  }
  renderSim(pH,s,f);
}
$('sim100').onclick=()=>runSim(100);
$('sim1000').onclick=()=>runSim(1000);
$('simReset').onclick=()=>{ sim={n:0,pos:0,posH:0,key:sim.key}; update(); };
function renderSim(pH,s,f){
  const post=(s*pH+f*(1-pH))>0 ? s*pH/(s*pH+f*(1-pH)) : 0;
  const frac = sim.pos ? sim.posH/sim.pos : 0;
  $('simOut').innerHTML = sim.n===0 ? '<span class="note">No people generated yet.</span>' :
    `${sim.n.toLocaleString()} people → <b>${sim.pos.toLocaleString()}</b> showed the evidence → <b class="hl-h">${sim.posH.toLocaleString()}</b> of those really H = <b>${sim.pos?pct(frac):'–'}</b> (theory ${pct(post)})`;
  $('simBar').style.width=(frac*100)+'%';
  $('simTheory').style.left=`calc(${post*100}% - 1px)`;
}

// ---------- extras: chain, odds, curve, sim ----------
function odds(p){ if(p<=0) return '0'; if(p>=1) return '∞'; const o=p/(1-p); return o>=1 ? (o>=100?o.toFixed(0):o.toFixed(1).replace(/\.0$/,''))+' : 1' : '1 : '+((1/o)>=100?(1/o).toFixed(0):(1/o).toFixed(1).replace(/\.0$/,'')); }
function extras(pH,s,f,post){
  // chain
  $('chain').innerHTML = hist.length ? hist.map((h,i)=>
     (i? `<span>→</span>`:'')+`<span class="chip ${i? (h.pos?'pos':'neg'):''}">${i? (h.pos?'E seen: ':'no E: '):'start '}${pct(h.v)}</span>`).join('')
     : '<span class="note">Start by clicking a button.</span>';
  $('chainNote').textContent = hist.length>2 ? `After ${hist.length-1} observations your belief is ${pct(post)}. Repeated positives can overcome a tiny prior; a negative pulls it back down.` : '';

  // odds
  const lr = f>0 ? s/f : Infinity;
  const priorO = pH/(1-pH), postO = isFinite(lr)? priorO*lr : Infinity;
  $('oPrior').textContent=odds(pH);
  $('oLR').textContent=isFinite(lr)? lr.toFixed(lr>=10?0:1).replace(/\.0$/,'')+' : 1' : '∞';
  $('oPost').textContent=odds(post);
  $('oNote').textContent = !isFinite(lr) ? 'With no false alarms, the evidence is conclusive.' :
    lr>1 ? `The evidence is ${lr.toFixed(1)}× more likely if H is true, so it multiplies the odds by ${lr.toFixed(1)}. If the prior odds are tiny, even a big multiplier leaves modest odds.` :
    lr<1 ? `The evidence is more likely if H is false, so it counts against H.` : 'The evidence is equally likely either way, so it tells you nothing.';

  // curve
  const X0=40,Y0=10,W=265,H=215, px=p=>X0+p*W, py=q=>Y0+H-q*H;
  const P=p=>{const d=s*p+f*(1-p); return d>0? s*p/d : 0;};
  let c='';
  for(let t=0;t<=4;t++){ const v=t/4;
    c+=`<line x1="${X0}" x2="${X0+W}" y1="${py(v)}" y2="${py(v)}" stroke="var(--line)"/>`+
       `<text x="${X0-6}" y="${py(v)+4}" font-size="10" text-anchor="end" fill="var(--muted)">${v*100}%</text>`+
       `<text x="${px(v)}" y="${Y0+H+14}" font-size="10" text-anchor="middle" fill="var(--muted)">${v*100}%</text>`; }
  c+=`<line x1="${px(0)}" y1="${py(0)}" x2="${px(1)}" y2="${py(1)}" stroke="var(--muted)" stroke-dasharray="4 4"/>`;
  let d=''; for(let i=0;i<=200;i++){ const p=i/200; d+=(i?'L':'M')+px(p).toFixed(1)+','+py(P(p)).toFixed(1); }
  c+=`<path d="${d}" fill="none" stroke="var(--h)" stroke-width="2.5"/>`;
  c+=`<line x1="${px(pH)}" x2="${px(pH)}" y1="${py(0)}" y2="${py(post)}" stroke="var(--fg)" stroke-dasharray="2 3"/>`+
     `<line x1="${px(0)}" x2="${px(pH)}" y1="${py(post)}" y2="${py(post)}" stroke="var(--fg)" stroke-dasharray="2 3"/>`+
     `<circle cx="${px(pH)}" cy="${py(post)}" r="5.5" fill="var(--f)" stroke="var(--bg)" stroke-width="2"/>`;
  const right = pH>0.6;
  c+=`<text x="${px(pH)+(right?-9:9)}" y="${py(post)+(post>0.85?16:-9)}" font-size="11" font-weight="600" text-anchor="${right?'end':'start'}" fill="var(--fg)">${pct(pH)} → ${pct(post)}</text>`;
  c+=`<text x="${X0+W/2}" y="${Y0+H+32}" font-size="11" text-anchor="middle" fill="var(--muted)">prior P(H)</text>`+
     `<text transform="translate(11 ${Y0+H/2}) rotate(-90)" font-size="11" text-anchor="middle" fill="var(--muted)">posterior P(H|E)</text>`;
  $('curve').innerHTML=c;

  // sim (reset when parameters change)
  const key=[pH.toFixed(5),s,f].join('|');
  if(key!==sim.key) sim={n:0,pos:0,posH:0,key};
  renderSim(pH,s,f);
}
update();
"""
